import sys

def solve():
    import sys
    input = sys.stdin.read().split()

    index = 0
    t = int(input[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(input[index])
        index += 1

        # Determine the winner based on the rules
        if (n + 1) % 3 == 0 or (n - 1) % 3 == 0:
            results.append("First")
        else:
            results.append("Second")

    for result in results:
        print(result)

if __name__ == '__main__':
    solve()
